        "t": "B΄ Ἰδιόμελον Ποίημα Λέοντος Δεσπότου. Δεῦτε λαοί, τὸ παράδοξον θαῦμα καθορῶντες, τοῦ Σταυροῦ τὴν δύναμιν προσκυνήσωμεν· ὅτι ξύλον ἐν Παραδείσῳ θάνατον ἐβλάστησε· τὸ δέ, τὴν ζωὴν ἐξήνθησεν, ἀναμάρτητον ἔχον προσηλωμένον τὸν Κύριον, ἐξ οὗ πάντα τὰ ἔθνη, ἀφθαρσίαν τρυγῶντες, κραυγάζομεν· Ὁ διὰ Σταυροῦ θάνατον καταργήσας, καὶ ἡμᾶς ἐλευθερώσας, δόξα σοι."
