        "t": "Ε΄ Ἰδιόμελον Ποίημα Λέοντος Δεσπότου. Ὁ τετραπέρατος κόσμος σήμερον ἁγιάζεται, τοῦ τετραμεροῦς ὑψουμένου σου Σταυροῦ, Χριστὲ ὁ Θεὸς ἡμῶν, καὶ τὸ κέρας τῶν πιστῶν, συνυψοῦται βασιλέων ἡμῶν, ἐν αὐτῷ τῶν δυσμενῶν συντριβόντων τὰ κέρατα. Μέγας εἶ Κύριε, καὶ θαυμαστὸς ἐν τοῖς ἔργοις σου! δόξα σοι."
